<template><view class="page"><text class="title">未来职业探索墙</text><view v-for="item in categories" :key="item.categoryId" class="card" @click="open(item)"><text>{{item.name}}</text><text>{{item.explorableCount == null ? 9 : item.explorableCount}} 个职业</text></view></view></template>
<script>import{getCatalog,getRecord,userMessage}from'@/api/zycck';export default{data:()=>({recordId:'',instanceId:'',gameId:'',categories:[]}),onLoad(o){Object.assign(this,{recordId:o.recordId||'',instanceId:o.instanceId||'',gameId:o.gameId||''});this.load()},methods:{async load(){try{const r=await getCatalog({instanceId:this.instanceId,gameId:this.gameId});const d=r.data||{};const rows=d.careers||[];let picked=[];if(this.recordId){try{const rr=await getRecord(this.recordId);const raw=rr.data&&((rr.data.record&&rr.data.record.careerIds)||rr.data.careerIds);picked=Array.isArray(raw)?raw:JSON.parse(raw||'[]')}catch(e){}}this.categories=(d.categories||[]).map(c=>({...c,explorableCount:Math.max(0,rows.filter(q=>String(q.categoryId)===String(c.categoryId)&&String(q.hasQuestion)!=='1'&&!picked.some(id=>String(id)===String(q.careerQuestionId))).length)}))}catch(e){uni.showToast({title:userMessage(e,'职业分类加载失败，请重试'),icon:'none'})}},open(item){uni.navigateTo({url:`/pages/zycck/careers?recordId=${this.recordId}&instanceId=${this.instanceId}&gameId=${this.gameId}&categoryId=${item.categoryId}`})}}}</script>
<style scoped>.page{padding:36rpx;background:#f5f7fb;min-height:100vh}.title{display:block;font-size:42rpx;font-weight:700;margin-bottom:30rpx}.card{display:flex;justify-content:space-between;background:#fff;padding:34rpx 28rpx;margin:18rpx 0;border-radius:16rpx;color:#243b53}</style>
